def transform(g, threshold=.5):
    h=len(g); w=len(g[0]); bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    seen=set(); rects=[]
    for r in range(h):
      for c in range(w):
        color=g[r][c]
        if color==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); pts=[]
        for y,x in q:
          pts.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==color:
              seen.add((yy,xx)); q.append((yy,xx))
        r0=min(y for y,x in pts); r1=max(y for y,x in pts); c0=min(x for y,x in pts); c1=max(x for y,x in pts)
        area=(r1-r0+1)*(c1-c0+1); density=len(pts)/area
        if area>=4 and density>=threshold:
          rects.append((color,r0,r1,c0,c1,density,len(pts)))
    out=[[bg]*w for _ in range(h)]
    for color,r0,r1,c0,c1,*_ in rects:
      for y in range(r0,r1+1):
       for x in range(c0,c1+1): out[y][x]=color
    return out,rects
